import { test, expect } from '@playwright/test';

test.describe('Multiple File Upload', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should successfully upload multiple files at once', async ({ page }) => {
    // Intercept the API endpoint for file upload
    await page.route('**/api/upload', (route) => {
      route.continue();
    });

    // Setup upload button using getByRole
    const uploadButton = page.getByRole('button', { name: /upload files/i });
    await expect(uploadButton).toBeVisible();

    // Setup file input using getByLabel
    const fileInput = page.getByLabel(/select files/i);
    await expect(fileInput).toBeVisible();

    // Upload first file
    const firstFile = page.waitForResponse(response =>
      response.url().includes('/api/upload') && response.status() === 200
    );
    await fileInput.setInputFiles('fixtures/sample-file1.pdf');
    await uploadButton.click();

    // Upload second file
    const secondFile = page.waitForResponse(response =>
      response.url().includes('/api/upload') && response.status() === 200
    );
    await fileInput.setInputFiles('fixtures/sample-file2.pdf');
    await uploadButton.click();

    // Verify success message
    const successMessage = page.getByText(/files uploaded successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify file count
    const fileCount = page.getByText(/2 files/i);
    await expect(fileCount).toBeVisible();

    // Verify file list
    const fileList = page.getByText(/sample-file1.pdf|sample-file2.pdf/i);
    await expect(fileList).toBeVisible();

    // Verify upload button is disabled after upload
    await expect(uploadButton).toBeDisabled();
  });

  test('should handle file upload failure and display error message', async ({ page }) => {
    // Intercept the API endpoint for file upload with error
    await page.route('**/api/upload', (route) => {
      route.abort('failed');
    });

    // Setup upload button using getByRole
    const uploadButton = page.getByRole('button', { name: /upload files/i });
    await expect(uploadButton).toBeVisible();

    // Setup file input using getByLabel
    const fileInput = page.getByLabel(/select files/i);
    await expect(fileInput).toBeVisible();

    // Upload first file
    const firstFile = page.waitForResponse(response =>
      response.url().includes('/api/upload') && response.status() === 200
    );
    await fileInput.setInputFiles('fixtures/sample-file1.pdf');
    await uploadButton.click();

    // Upload second file
    const secondFile = page.waitForResponse(response =>
      response.url().includes('/api/upload') && response.status() === 200
    );
    await fileInput.setInputFiles('fixtures/sample-file2.pdf');
    await uploadButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/file upload failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify file list is empty
    const fileList = page.getByText(/sample-file1.pdf|sample-file2.pdf/i);
    await expect(fileList).not.toBeVisible();

    // Verify upload button is enabled after error
    await expect(uploadButton).toBeEnabled();
  });
});
